/* Original lessons (Vietnamese explanations) for each roadmap chapter.
   u: dùng khi nào · t: bảng (hàng đầu là tiêu đề) · f: quy tắc · x: ví dụ [fr, vn] · e: lỗi hay gặp · en: so với tiếng Anh · q: tự kiểm tra [câu, đáp án] */
const LESSONS={};
LESSONS.I1={u:["Giới thiệu, nghề nghiệp, quốc tịch: Je suis étudiant.","Mô tả tính chất, trạng thái: Elle est fatiguée.","Nói vị trí: Nous sommes à Hanoï."],
t:[["Ngôi","être"],["je","suis"],["tu","es"],["il / elle / on","est"],["nous","sommes"],["vous","êtes"],["ils / elles","sont"]],
f:["tu dùng với bạn bè, người thân; vous dùng khi lịch sự hoặc nói với nhiều người.","on thường thay cho nous trong văn nói, chia như il: On est contents."],
x:[["Je suis vietnamien.","Tôi là người Việt."],["Vous êtes professeur ?","Ông/bà là giáo viên à?"],["Ils sont au bureau.","Họ đang ở văn phòng."],["C'est mon ami, il est très gentil.","Đây là bạn tôi, anh ấy rất tốt."]],
e:["Thêm mạo từ trước nghề nghiệp: Je suis un étudiant → Je suis étudiant.","Bỏ chủ ngữ: Est fatigué → Il est fatigué."],
en:"Giống to be, nhưng tuổi dùng avoir: J'ai 20 ans (không nói Je suis 20 ans).",
q:[["Nous ___ en retard.","sommes"],["Tu ___ française ?","es"],["Elles ___ à la maison.","sont"]]};
LESSONS.I2={u:["Tính từ hợp giống và số với danh từ hoặc chủ ngữ mà nó mô tả."],
f:["Giống cái: thường thêm -e (grand → grande). Tính từ tận cùng -e giữ nguyên (jeune).","Số nhiều: thêm -s (grands, grandes). Tận cùng -s, -x giữ nguyên (gris, heureux).","Đuôi đặc biệt: -eux → -euse (heureuse), -if → -ive (sportive), -en → -enne (italienne), -er → -ère (chère)."],
x:[["Il est petit. Elle est petite.","Anh ấy thấp. Cô ấy thấp."],["Mes amis sont sympathiques.","Các bạn tôi dễ mến."],["Ma mère est sportive.","Mẹ tôi chơi thể thao nhiều."],["Les rues sont calmes.","Các con phố yên tĩnh."]],
e:["Quên -e giống cái: Elle est content → Elle est contente.","Nhóm có cả nam lẫn nữ dùng giống đực số nhiều: Paul et Marie sont contents."],
en:"Tính từ tiếng Anh không đổi (tall, tall); tiếng Pháp luôn hợp giống và số.",
q:[["Elle est ___ (heureux).","heureuse"],["Ils sont ___ (fatigué).","fatigués"],["Une voiture ___ (cher).","chère"]]};
LESSONS.I3={u:["Phủ định: ne + động từ + pas.","Câu hỏi có/không: bằng ngữ điệu, bằng est-ce que, hoặc đảo ngữ."],
f:["ne → n' trước nguyên âm: Je n'aime pas.","Ba cách hỏi: Tu parles français ? / Est-ce que tu parles français ? / Parles-tu français ?","Khẳng định lại một câu hỏi phủ định bằng si: Tu ne viens pas ? – Si !"],
x:[["Je ne suis pas fatigué.","Tôi không mệt."],["Il n'habite pas ici.","Anh ấy không sống ở đây."],["Est-ce que vous êtes libre ?","Anh có rảnh không?"],["Tu n'aimes pas le café ? – Si, j'adore !","Bạn không thích cà phê à? – Có chứ, tôi mê!"]],
e:["Đặt pas sai chỗ: Je ne pas parle → Je ne parle pas.","Trả lời oui cho câu hỏi phủ định khi muốn khẳng định: phải dùng si."],
en:"Không có trợ động từ do: Do you speak…? → Tu parles… ?; I don't… → je ne… pas.",
q:[["Mettez au négatif : Elle travaille.","Elle ne travaille pas."],["Posez la question avec est-ce que : Il est là.","Est-ce qu'il est là ?"],["Tu n'es pas content ? – ___, je suis content !","Si"]]};
LESSONS.I4={u:["Mọi danh từ đều có giống đực hoặc giống cái.","Mạo từ không xác định (un, une, des) cho vật chưa xác định; mạo từ xác định (le, la, l', les) cho vật đã biết hoặc nói chung."],
t:[["","giống đực","giống cái","số nhiều"],["không xác định","un","une","des"],["xác định","le (l')","la (l')","les"]],
f:["Mạo từ rút gọn: à + le = au, à + les = aux; de + le = du, de + les = des.","Số nhiều thường thêm -s; -eau → -eaux; -al → -aux (journal → journaux)."],
x:[["J'ai un frère et une sœur.","Tôi có một anh trai và một chị gái."],["Le livre est sur la table.","Quyển sách ở trên bàn."],["Je vais au marché.","Tôi đi chợ."],["C'est le sac du professeur.","Đó là túi của thầy giáo."]],
e:["Không rút gọn: à le, de le → au, du.","Học danh từ kèm mạo từ để nhớ giống: la table, le livre."],
en:"The không có giống; tiếng Pháp phải chọn le hay la. Khi nói chung chung vẫn dùng mạo từ: J'aime le café (I like coffee).",
q:[["Je parle ___ (à + le) directeur.","au"],["C'est la voiture ___ (de + les) voisins.","des"],["___ (un/une) maison","une"]]};
LESSONS.I5={u:["C'est + danh từ có mạo từ hoặc từ hạn định: C'est un médecin.","Il / elle est + tính từ, hoặc nghề nghiệp không mạo từ: Il est médecin."],
f:["C'est + tên riêng, đại từ nhấn mạnh: C'est Marie. C'est moi.","C'est + tính từ giống đực để nhận xét chung: C'est beau !","Số nhiều: ce sont + danh từ."],
x:[["C'est mon professeur. Il est très patient.","Đó là thầy tôi. Thầy rất kiên nhẫn."],["Elle est journaliste.","Cô ấy là nhà báo."],["C'est une journaliste célèbre.","Đó là một nhà báo nổi tiếng."],["Paris ? C'est magnifique !","Paris à? Tuyệt đẹp!"]],
e:["Il est un médecin → Il est médecin hoặc C'est un médecin.","Elle est une amie → C'est une amie."],
en:"He is a doctor có a; tiếng Pháp bỏ mạo từ sau il est.",
q:[["___ un bon restaurant.","C'est"],["___ avocate. (elle)","Elle est"],["___ mes parents.","Ce sont"]]};
LESSONS.I6={u:["Tính từ sở hữu hợp giống và số với vật được sở hữu, không theo người sở hữu."],
t:[["","giống đực","giống cái","số nhiều"],["je","mon","ma","mes"],["tu","ton","ta","tes"],["il / elle","son","sa","ses"],["nous","notre","notre","nos"],["vous","votre","votre","vos"],["ils / elles","leur","leur","leurs"]],
f:["Trước danh từ giống cái bắt đầu bằng nguyên âm dùng mon, ton, son: mon amie.","Đại từ sở hữu: le mien, la mienne, les miens, les miennes; le tien; le sien; le nôtre; le vôtre; le leur."],
x:[["C'est sa voiture.","Đó là xe của anh ấy (hoặc cô ấy)."],["Mon école est grande.","Trường tôi lớn."],["Ce n'est pas mon stylo, c'est le tien.","Không phải bút của tôi, là của bạn."],["Ils aiment leurs enfants.","Họ yêu con cái của họ."]],
e:["sa vélo → son vélo (vélo giống đực).","ma amie → mon amie."],
en:"his/her theo người sở hữu; son/sa theo vật: sa mère = his mother hoặc her mother.",
q:[["C'est ___ (je) adresse.","mon"],["Ils prennent ___ (ils) voiture.","leur"],["Ce livre est à toi ? – Oui, c'est ___.","le mien"]]};
LESSONS.I7={u:["Từ chỉ quan hệ gia đình và danh từ chỉ tập hợp người."],
f:["Gia đình: le père, la mère, les parents, le frère, la sœur, le grand-père, l'oncle, la tante, le cousin, la cousine, le neveu, la nièce.","beau- / belle- chỉ họ hàng bên vợ hoặc chồng, hoặc quan hệ kế: le beau-père, la belle-sœur.","Danh từ tập hợp (la famille, la foule, le groupe) đi với động từ số ít: La famille est réunie."],
x:[["Mes parents habitent à Huế.","Bố mẹ tôi sống ở Huế."],["J'ai deux cousins et une cousine.","Tôi có hai anh em họ và một chị họ."],["Le groupe part à 9 heures.","Cả nhóm khởi hành lúc 9 giờ."],["Ma belle-sœur est infirmière.","Chị dâu tôi là y tá."]],
e:["La famille sont… → La famille est…","Quên rằng les parents có thể là họ hàng nói chung, không chỉ bố mẹ."],
en:"parents (tiếng Anh) chỉ bố mẹ; les parents trong tiếng Pháp còn có nghĩa là họ hàng (relatives).",
q:[["Le frère de mon père est mon ___.","oncle"],["La fille de ma sœur est ma ___.","nièce"],["La foule ___ (être) nombreuse.","est"]]};
LESSONS.I8={u:["Chỉ định người hoặc vật: ce livre, cette ville."],
t:[["","giống đực","giống cái"],["số ít","ce / cet","cette"],["số nhiều","ces","ces"]],
f:["cet trước danh từ giống đực bắt đầu bằng nguyên âm hoặc h câm: cet homme.","-ci chỉ gần, -là chỉ xa: ce livre-ci / ce livre-là.","Đại từ chỉ định: celui, celle, ceux, celles (+ -ci / -là, de, qui): Je préfère celui-ci."],
x:[["Cette robe est jolie.","Cái váy này đẹp."],["Cet hôtel est cher.","Khách sạn này đắt."],["Quel gâteau veux-tu ? – Celui-là.","Bạn muốn bánh nào? – Cái kia."],["Ces enfants sont mes neveux.","Những đứa trẻ này là cháu tôi."]],
e:["ce hôtel → cet hôtel.","Dùng sai giống của đại từ: robe → celle-là, không phải celui-là."],
en:"this và that cùng là ce; phân biệt gần xa bằng -ci / -là.",
q:[["___ arbre est très vieux.","Cet"],["___ chaussures sont neuves.","Ces"],["Tu veux cette pomme ou ___-là ?","celle"]]};
LESSONS.I9={u:["Il y a + danh từ: nói sự tồn tại (có).","C'est: xác định hoặc giới thiệu cái đang nói tới."],
f:["Phủ định: il n'y a pas de + danh từ.","Thường đi thành cặp: Il y a un musée. C'est le musée d'Orsay.","Qu'est-ce qu'il y a ? = Có chuyện gì vậy? / Có gì?"],
x:[["Il y a un café près d'ici.","Gần đây có một quán cà phê."],["Il n'y a pas de lait.","Không có sữa."],["Qu'est-ce que c'est ? – C'est un cadeau.","Cái gì vậy? – Một món quà."],["Il y a beaucoup de monde.","Có rất đông người."]],
e:["Il y a pas du lait → Il n'y a pas de lait.","Dùng c'est để nói có: C'est un parc ici → Il y a un parc ici."],
en:"il y a = there is / there are, không đổi theo số ít hay số nhiều.",
q:[["___ trois chambres dans l'appartement.","Il y a"],["Mettez au négatif : Il y a du pain.","Il n'y a pas de pain."],["Qu'est-ce que c'est ? – ___ un dictionnaire.","C'est"]]};
LESSONS.I10={u:["Giới từ đứng trước tên thành phố, quốc gia, châu lục."],
t:[["Nơi","ở / đến","từ"],["thành phố","à Paris","de Paris"],["nước giống cái","en France","de France"],["nước giống đực","au Japon","du Japon"],["nước số nhiều","aux États-Unis","des États-Unis"]],
f:["Nước giống đực bắt đầu bằng nguyên âm dùng en: en Iran.","Châu lục dùng en: en Europe, en Asie, en Afrique."],
x:[["J'habite à Đà Nẵng, au Việt Nam.","Tôi sống ở Đà Nẵng, Việt Nam."],["Elle travaille en Allemagne.","Cô ấy làm việc ở Đức."],["Il revient du Canada.","Anh ấy từ Canada về."],["Nous allons aux Pays-Bas.","Chúng tôi đi Hà Lan."]],
e:["en Japon → au Japon.","à France → en France."],
en:"Tiếng Anh dùng in / to cho mọi nơi; tiếng Pháp đổi giới từ theo giống và số của tên nước.",
q:[["Il habite ___ Portugal.","au"],["Je vais ___ Italie.","en"],["Elle vient ___ Mexique.","du"]]};
LESSONS.I11={u:["Sở hữu: J'ai une voiture.","Tuổi và cảm giác: avoir 20 ans, avoir faim, soif, chaud, froid, peur, sommeil.","Thành ngữ: avoir besoin de, avoir envie de, avoir le temps de, avoir mal à."],
t:[["Ngôi","avoir"],["je","ai (j'ai)"],["tu","as"],["il / elle / on","a"],["nous","avons"],["vous","avez"],["ils / elles","ont"]],
f:["Phủ định: un / une / des → de: Je n'ai pas de voiture.","Mô tả ngoại hình: avoir les yeux bleus, avoir les cheveux longs."],
x:[["J'ai 19 ans.","Tôi 19 tuổi."],["Tu as faim ?","Bạn đói không?"],["Elle a les yeux noirs.","Cô ấy có đôi mắt đen."],["Nous n'avons pas de temps.","Chúng tôi không có thời gian."]],
e:["Je suis 19 ans → J'ai 19 ans.","Je suis faim → J'ai faim."],
en:"I'm hungry, I'm 19 dùng to be; tiếng Pháp dùng avoir.",
q:[["Ils ___ deux enfants.","ont"],["J'___ mal à la tête.","ai"],["Mettez au négatif : Il a des frères.","Il n'a pas de frères."]]};
LESSONS.I12={u:["Phần lớn tính từ đứng sau danh từ: une robe rouge, un livre intéressant."],
f:["Một số tính từ ngắn, thông dụng đứng trước: beau, joli, grand, petit, bon, mauvais, jeune, vieux, nouveau, gros.","beau, nouveau, vieux → bel, nouvel, vieil trước danh từ giống đực bắt đầu bằng nguyên âm.","Một số tính từ đổi nghĩa theo vị trí: un grand homme (vĩ nhân) / un homme grand (người cao); mon ancien professeur (thầy cũ) / un meuble ancien (đồ cổ)."],
x:[["Une petite maison blanche.","Một ngôi nhà nhỏ màu trắng."],["Un bel appartement.","Một căn hộ đẹp."],["Un film français très drôle.","Một bộ phim Pháp rất hài."],["Mon ancien patron.","Sếp cũ của tôi."]],
e:["une rouge robe → une robe rouge.","un beau ami → un bel ami."],
en:"Tính từ tiếng Anh luôn đứng trước (a red dress); tiếng Pháp thường đứng sau.",
q:[["(nouveau) un ___ hôtel","nouvel"],["Mettez dans l'ordre : voiture / une / rouge","une voiture rouge"],["« un grand homme » signifie…","un homme célèbre, important"]]};
LESSONS.I13={u:["Số đếm, số thứ tự, cách đọc và viết số."],
f:["70 = soixante-dix, 80 = quatre-vingts, 90 = quatre-vingt-dix; 71 = soixante et onze.","quatre-vingts và cent thêm -s khi được nhân lên và đứng cuối: deux cents, nhưng deux cent trois, quatre-vingt-deux.","mille không bao giờ thêm -s: deux mille.","Số thứ tự: thêm -ième (deuxième, troisième); riêng premier / première; cinq → cinquième, neuf → neuvième."],
x:[["Il a quatre-vingt-deux ans.","Ông ấy 82 tuổi."],["C'est la première fois.","Đây là lần đầu."],["Il habite au troisième étage.","Anh ấy sống ở tầng ba (tầng 4 kiểu Việt)."],["Ça coûte deux cent cinquante euros.","Giá 250 euro."]],
e:["quatre-vingts-deux → quatre-vingt-deux.","deux milles → deux mille."],
en:"le premier étage là tầng ngay trên tầng trệt (rez-de-chaussée), tức tầng 2 theo cách đếm của Việt Nam.",
q:[["Écrivez 75 en lettres.","soixante-quinze"],["Écrivez 300 en lettres.","trois cents"],["5 → nombre ordinal","cinquième"]]};
LESSONS.I14={u:["Nói ngày tháng, mùa, giờ và thời tiết."],
f:["Ngày: le lundi 3 mai; ngày mùng 1: le premier mai.","Tháng: en mai / au mois de mai. Mùa: au printemps, en été, en automne, en hiver.","Giờ: Il est 8 heures et quart / et demie / 9 heures moins le quart; midi, minuit.","Thời tiết: il fait beau, chaud, froid; il pleut, il neige."],
x:[["Nous sommes le 14 juillet.","Hôm nay là 14 tháng 7."],["Il est neuf heures moins le quart.","Bây giờ là 8 giờ 45."],["En hiver, il fait froid à Hà Nội.","Mùa đông Hà Nội lạnh."],["Le lundi, je vais à la piscine.","Thứ Hai nào tôi cũng đi bơi."]],
e:["en printemps → au printemps.","Il est froid (nói về thời tiết) → Il fait froid."],
en:"le lundi = every Monday, lundi = this Monday. Tiếng Pháp không viết hoa thứ và tháng.",
q:[["___ été, il fait chaud.","En"],["14 h 30 : il est deux heures et ___.","demie"],["Il ___ beau aujourd'hui.","fait"]]};
LESSONS.I15={u:["Chỉ người hoặc vật không xác định."],
f:["Tính từ: chaque (mỗi, đi với số ít), quelques (vài), plusieurs (nhiều), certains, tout / toute / tous / toutes.","Đại từ: quelqu'un ↔ personne; quelque chose ↔ rien; chacun(e).","Thêm tính từ: quelque chose de + tính từ giống đực: quelque chose d'intéressant."],
x:[["Quelqu'un a téléphoné.","Có ai đó đã gọi điện."],["Je n'ai rien vu.","Tôi không thấy gì."],["Chaque étudiant a un livre.","Mỗi sinh viên có một cuốn sách."],["J'ai quelque chose d'important à te dire.","Tôi có điều quan trọng muốn nói với bạn."]],
e:["chaque étudiants → chaque étudiant.","quelque chose d'intéressante → quelque chose d'intéressant."],
en:"nothing / nobody vẫn cần ne: je ne vois rien, je ne vois personne.",
q:[["Il y a ___ ? – Non, il n'y a personne.","quelqu'un"],["___ (mỗi) jour, je cours.","Chaque"],["J'ai acheté ___ (vài) pommes.","quelques"]]};
LESSONS.I16={u:["Nhóm động từ đông nhất: parler, aimer, habiter, travailler…"],
t:[["Ngôi","parler"],["je","parle"],["tu","parles"],["il / elle / on","parle"],["nous","parlons"],["vous","parlez"],["ils / elles","parlent"]],
f:["je parle, tu parles, il parle, ils parlent đọc giống nhau: đuôi -e, -es, -ent câm.","-ger: nous mangeons; -cer: nous commençons.","Một số đổi dấu hoặc gấp đôi phụ âm: j'achète, j'appelle, je préfère (nhưng nous achetons, nous appelons, nous préférons)."],
x:[["J'habite à Hồ Chí Minh-Ville.","Tôi sống ở TP. Hồ Chí Minh."],["Nous mangeons à midi.","Chúng tôi ăn trưa lúc 12 giờ."],["Ils travaillent beaucoup.","Họ làm việc nhiều."],["Tu préfères le thé ?","Bạn thích trà hơn à?"]],
e:["Đọc âm cuối -ent: ils parlent đọc như il parle.","nous mangons → nous mangeons."],
en:"Tiếng Anh chỉ thêm -s ở ngôi thứ ba số ít; tiếng Pháp có đuôi riêng cho từng ngôi.",
q:[["Vous ___ (aimer) le cinéma ?","aimez"],["Nous ___ (commencer) à 8 h.","commençons"],["J'___ (acheter) du pain.","achète"]]};
LESSONS.I17={u:["Diễn đạt khoảng thời gian."],
f:["depuis + hiện tại: việc bắt đầu trong quá khứ và vẫn đang tiếp diễn.","pendant: khoảng thời gian, thường đã hoặc sẽ kết thúc.","pour: khoảng thời gian dự định (hay đi với partir, venir, être là).","en: thời gian cần để làm xong một việc."],
x:[["J'étudie le français depuis un an.","Tôi học tiếng Pháp được một năm rồi."],["J'ai dormi pendant huit heures.","Tôi đã ngủ tám tiếng."],["Il part à Paris pour une semaine.","Anh ấy đi Paris một tuần."],["J'ai fait ce travail en deux heures.","Tôi làm xong việc này trong hai tiếng."]],
e:["J'étudie le français pendant un an (khi vẫn đang học) → depuis.","Dùng passé composé với depuis khi việc vẫn tiếp diễn: phải dùng thì hiện tại."],
en:"I have been studying for a year → J'étudie depuis un an (thì hiện tại).",
q:[["Il pleut ___ ce matin.","depuis"],["Elle a vécu à Rome ___ trois ans.","pendant"],["J'ai lu le livre ___ une journée.","en"]]};
LESSONS.I18={u:["Bổ nghĩa cho động từ, tính từ hoặc trạng từ khác."],
f:["-ment thêm vào tính từ giống cái: lent → lente → lentement; heureux → heureusement.","Tính từ tận cùng bằng nguyên âm: vrai → vraiment, poli → poliment.","-ant → -amment, -ent → -emment: courant → couramment, prudent → prudemment.","bon → bien, mauvais → mal. Trạng từ thời gian và nơi chốn: toujours, souvent, déjà, ici, là-bas."],
x:[["Il parle couramment anglais.","Anh ấy nói tiếng Anh trôi chảy."],["Elle conduit prudemment.","Cô ấy lái xe cẩn thận."],["Tu chantes bien !","Bạn hát hay!"],["Je vais souvent au cinéma.","Tôi hay đi xem phim."]],
e:["Il travaille bon → Il travaille bien.","prudentment → prudemment."],
en:"-ment ≈ -ly. Trạng từ thường đứng ngay sau động từ, không chen giữa chủ ngữ và động từ như I often go.",
q:[["rapide → ___","rapidement"],["évident → ___","évidemment"],["Elle danse très ___ (bon / bien).","bien"]]};
LESSONS.I19={u:["Diễn đạt số lượng không xác định và xác định."],
f:["Mạo từ bộ phận du, de la, de l', des: một ít, lượng không đếm.","Lượng xác định + de: un kilo de, une bouteille de, beaucoup de, peu de, trop de, assez de.","Phủ định: pas de: Je ne bois pas de café."],
x:[["Je voudrais du fromage et de la salade.","Cho tôi ít phô mai và rau trộn."],["Il y a beaucoup de touristes.","Có rất nhiều khách du lịch."],["Un litre de lait, s'il vous plaît.","Cho một lít sữa."],["Je n'ai pas assez d'argent.","Tôi không đủ tiền."]],
e:["beaucoup des amis → beaucoup d'amis.","un kilo des tomates → un kilo de tomates."],
en:"some / any thường dịch bằng du, de la, des; tiếng Pháp không bỏ mạo từ được như trong I eat bread.",
q:[["Je bois ___ eau.","de l'"],["Il mange trop ___ sucre.","de"],["Mettez au négatif : J'ai du temps.","Je n'ai pas de temps."]]};
LESSONS.I20={u:["Thay cho de + danh từ, hoặc danh từ đi với mạo từ bộ phận hay chỉ số lượng."],
f:["Đứng trước động từ: J'en veux.","Với số lượng, giữ con số ở cuối câu: J'en ai deux.","Với động từ đi với de: parler de, avoir besoin de → J'en parle, j'en ai besoin."],
x:[["Tu veux du pain ? – Oui, j'en veux.","Bạn muốn bánh mì không? – Có."],["Combien de sœurs as-tu ? – J'en ai une.","Bạn có mấy chị em gái? – Một."],["Il parle de son voyage ? – Oui, il en parle souvent.","Anh ấy kể về chuyến đi à? – Ừ, kể suốt."],["Je n'en ai pas.","Tôi không có (cái đó)."]],
e:["J'ai deux (thiếu en) → J'en ai deux.","Je le veux để thay du pain → J'en veux."],
en:"en ≈ some / any / of it / of them; tiếng Anh hay bỏ, tiếng Pháp bắt buộc phải có.",
q:[["Tu as des stylos ? – Oui, j'___ ai trois.","en"],["Vous mangez de la viande ? – Non, je n'___ mange pas.","en"],["Elle a besoin de ton aide ? – Oui, elle ___ a besoin.","en"]]};
LESSONS.I21={u:["Nói vùng, tỉnh và nguồn gốc địa lý."],
f:["Vùng giống cái: en Bretagne, en Normandie. Với một số vùng và hướng: dans le Nord, dans le Sud.","Tỉnh (département): dans le Var, dans la Drôme.","Nguồn gốc: venir de, être originaire de. Tính từ nguồn gốc: breton, normand, parisien."],
x:[["Ils passent l'été en Provence.","Họ nghỉ hè ở Provence."],["Ma famille habite dans le Sud.","Gia đình tôi sống ở miền Nam."],["Elle est originaire d'Alsace.","Cô ấy gốc Alsace."],["Le camembert vient de Normandie.","Phô mai camembert đến từ Normandie."]],
e:["à Bretagne → en Bretagne.","Tính từ nguồn gốc viết thường (un fromage normand); danh từ chỉ người viết hoa (un Normand)."],
en:"Tiếng Anh viết hoa tính từ quốc tịch (French); tiếng Pháp viết thường (français).",
q:[["Ils vivent ___ Normandie.","en"],["Il habite ___ Nord.","dans le"],["Elle vient ___ Alsace.","d'"]]};
LESSONS.I22={u:["So sánh hơn, kém, bằng và so sánh nhất."],
f:["plus / moins / aussi + tính từ hoặc trạng từ + que.","plus de / moins de / autant de + danh từ + que.","So sánh nhất: le / la / les plus (moins) + tính từ (+ de + nhóm).","bon → meilleur, le meilleur; bien → mieux, le mieux."],
x:[["En hiver, Hà Nội est plus froid que Hồ Chí Minh-Ville.","Mùa đông Hà Nội lạnh hơn TP. HCM."],["Elle a autant de livres que moi.","Cô ấy có nhiều sách bằng tôi."],["C'est le meilleur restaurant du quartier.","Đây là nhà hàng ngon nhất khu."],["Il parle mieux français que l'année dernière.","Anh ấy nói tiếng Pháp giỏi hơn năm ngoái."]],
e:["plus bon → meilleur.","plus bien → mieux."],
en:"the best in the world → le meilleur du monde (dùng de, không dùng dans).",
q:[["Ce gâteau est ___ que l'autre. (bon, +)","meilleur"],["Il court ___ vite ___ son frère. (=)","aussi / que"],["C'est la ville la ___ peuplée du pays. (+)","plus"]]};
LESSONS.I23={u:["Đi đến một nơi; hỏi thăm sức khỏe; tạo tương lai gần (aller + nguyên mẫu)."],
t:[["Ngôi","aller"],["je","vais"],["tu","vas"],["il / elle / on","va"],["nous","allons"],["vous","allez"],["ils / elles","vont"]],
f:["aller à + nơi chốn (au, à la, aux); aller chez + người.","Phương tiện: en voiture, en train, en avion, en bus; à pied, à vélo, à moto."],
x:[["Je vais à l'université à vélo.","Tôi đi xe đạp đến trường."],["Comment vas-tu ? – Je vais bien.","Bạn khỏe không? – Tôi khỏe."],["Nous allons chez le dentiste.","Chúng tôi đi nha sĩ."],["Ils vont en Italie en train.","Họ đi Ý bằng tàu."]],
e:["Je vais à le cinéma → Je vais au cinéma.","en pied → à pied."],
en:"go by car → en voiture; on foot → à pied.",
q:[["Vous ___ au marché ?","allez"],["Elle va au travail ___ pied.","à"],["Je vais ___ mes grands-parents.","chez"]]};
LESSONS.I24={u:["Thay cho nơi chốn đã nhắc tới (à, en, dans, chez + nơi).","Thay cho à + vật hoặc ý tưởng: penser à, s'intéresser à, répondre à (một vật)."],
f:["Đứng trước động từ: J'y vais. Phủ định: Je n'y vais pas.","Không dùng y cho người: penser à quelqu'un → penser à lui / à elle."],
x:[["Tu vas à Huế ? – Oui, j'y vais demain.","Bạn đi Huế à? – Ừ, mai tôi đi."],["Elle habite en France ? – Oui, elle y habite depuis 2020.","Cô ấy sống ở Pháp à? – Ừ, từ năm 2020."],["Tu penses à ton examen ? – Oui, j'y pense.","Bạn nghĩ về kỳ thi à? – Ừ."],["On y va !","Đi thôi!"]],
e:["Dùng y cho người: J'y pense (về mẹ) → Je pense à elle.","Quên y với aller: Je vais demain → J'y vais demain."],
en:"y ≈ there / about it; tiếng Anh hay bỏ, tiếng Pháp phải có.",
q:[["Tu restes à la maison ? – Oui, j'___ reste.","y"],["Vous répondez à la lettre ? – Oui, nous ___ répondons.","y"],["Tu penses à ta mère ? – Oui, je pense ___.","à elle"]]};
LESSONS.I25={u:["Giới từ chỉ điểm bắt đầu, điểm kết thúc và khoảng cách trong không gian, thời gian."],
f:["de … à: du lundi au vendredi, de 9 h à 17 h, de Paris à Lyon.","jusqu'à: đến tận: jusqu'à minuit, jusqu'à la gare.","à partir de: kể từ: à partir de demain.","à + khoảng cách / thời gian di chuyển: à 10 km, à deux heures de Paris."],
x:[["Le magasin est ouvert de 9 h à 19 h.","Cửa hàng mở từ 9 giờ đến 19 giờ."],["Je travaille jusqu'à 18 heures.","Tôi làm đến 6 giờ chiều."],["La plage est à cinq minutes à pied.","Bãi biển cách 5 phút đi bộ."],["À partir de lundi, je fais du sport.","Từ thứ Hai, tôi chơi thể thao."]],
e:["jusqu'à le soir → jusqu'au soir.","Lịch cố định hằng tuần nên nói du lundi au vendredi."],
en:"until → jusqu'à; from… to… → de… à…",
q:[["Les cours ont lieu ___ lundi ___ jeudi.","du / au"],["Il reste ___ la fin du film.","jusqu'à"],["Le village est ___ 20 km d'ici.","à"]]};
LESSONS.I26={u:["Động từ nhóm 2 (như finir) và nhóm 3 (bất quy tắc)."],
t:[["","finir","prendre","pouvoir"],["je","finis","prends","peux"],["nous","finissons","prenons","pouvons"],["ils","finissent","prennent","peuvent"]],
f:["Nhóm 2 (-ir, nous -issons): finir, choisir, réussir, grandir.","Động từ có hai hoặc ba gốc: partir (je pars, nous partons), venir (je viens, nous venons, ils viennent), boire, devoir, recevoir.","Bất quy tắc phải thuộc: être, avoir, aller, faire (vous faites), dire (vous dites), mettre, savoir, connaître, vouloir, falloir (il faut)."],
x:[["Je finis à 17 h.","Tôi xong việc lúc 5 giờ chiều."],["Vous faites du sport ?","Anh chị có chơi thể thao không?"],["Ils prennent le métro.","Họ đi tàu điện ngầm."],["Je ne sais pas.","Tôi không biết."]],
e:["vous faisez → vous faites.","ils prendent → ils prennent."],
en:"savoir = biết thông tin, kỹ năng; connaître = biết người, nơi chốn. I know Paul → Je connais Paul.",
q:[["Nous ___ (choisir) un film.","choisissons"],["Ils ___ (venir) ce soir.","viennent"],["Vous ___ (dire) la vérité ?","dites"]]};
LESSONS.I27={u:["Phản thân: hành động tác động lên chính mình (se laver).","Tương hỗ: làm cho nhau (se téléphoner).","Một số động từ luôn có se: se souvenir, s'en aller."],
t:[["se lever"],["je me lève"],["tu te lèves"],["il / elle se lève"],["nous nous levons"],["vous vous levez"],["ils / elles se lèvent"]],
f:["Passé composé dùng être: Elle s'est levée.","Phủ định: Je ne me lève pas.","Mệnh lệnh khẳng định: Lève-toi ! Dépêchons-nous !"],
x:[["Je me réveille à 6 h.","Tôi thức dậy lúc 6 giờ."],["Ils se parlent tous les jours.","Họ nói chuyện với nhau mỗi ngày."],["Tu te souviens de moi ?","Bạn còn nhớ tôi không?"],["Nous nous sommes promenés.","Chúng tôi đã đi dạo."]],
e:["Je lave les mains → Je me lave les mains.","Elle a levé tôt (nghĩa là thức dậy) → Elle s'est levée tôt."],
en:"Tiếng Anh thường không có đại từ phản thân: I wake up → je me réveille.",
q:[["Nous ___ (s'habiller) vite.","nous habillons"],["Elle ___ (se coucher, passé composé) tard.","s'est couchée"],["Mettez à l'impératif : tu te dépêches.","Dépêche-toi !"]]};
LESSONS.I28={u:["Đại từ tân ngữ trực tiếp (COD): me, te, le, la, nous, vous, les.","Đại từ tân ngữ gián tiếp (COI, à + người): me, te, lui, nous, vous, leur."],
f:["Đứng trước động từ; ở passé composé đứng trước trợ động từ; trước nguyên mẫu nếu có: Je le vois. Je l'ai vu. Je vais le voir.","Thứ tự khi có hai đại từ: me / te / nous / vous → le / la / les → lui / leur → y → en. Je te le donne. Je le lui donne.","Passé composé: phân từ hợp với COD đứng trước: Les photos ? Je les ai prises."],
x:[["Tu connais Marc ? – Oui, je le connais.","Bạn biết Marc à? – Biết."],["Je téléphone à Lan. → Je lui téléphone.","Tôi gọi cho Lan."],["Le livre ? Je te le prête.","Quyển sách à? Tôi cho bạn mượn."],["Les clés ? Je les ai perdues.","Chìa khóa à? Tôi làm mất rồi."]],
e:["Je lui aime → Je l'aime (aimer đi với COD).","Je leur vois → Je les vois."],
en:"Đại từ đứng trước động từ: I see him → je le vois.",
q:[["Tu parles à tes parents ? – Oui, je ___ parle.","leur"],["Tu donnes la lettre à Paul ? – Oui, je ___ ___ donne.","la lui"],["La robe ? Je l'ai ___ (acheter).","achetée"]]};
LESSONS.I29={u:["Nhấn mạnh: Moi, je…","Sau giới từ: avec moi, chez lui, pour eux.","Sau c'est, sau que trong so sánh, trong câu trả lời ngắn: Moi aussi, Moi non plus."],
t:[["Chủ ngữ","Đại từ nhấn mạnh"],["je","moi"],["tu","toi"],["il / elle","lui / elle"],["nous","nous"],["vous","vous"],["ils / elles","eux / elles"]],
f:["penser à, s'intéresser à + người → à + đại từ nhấn mạnh: Je pense à toi."],
x:[["Lui, il adore le foot.","Anh ấy thì mê bóng đá."],["Tu viens avec nous ?","Bạn đi với chúng tôi không?"],["C'est elle qui a raison.","Chính cô ấy đúng."],["J'aime le jazz. – Moi aussi !","Tôi thích jazz. – Tôi cũng vậy!"]],
e:["avec je → avec moi.","plus grand que il → plus grand que lui."],
en:"me / him sau giới từ ≈ moi / lui: for me → pour moi.",
q:[["C'est ___ (tu) ?","toi"],["Il est plus âgé que ___ (je).","moi"],["Je n'aime pas le thé. – ___ non plus.","Moi"]]};
LESSONS.I30={u:["Ra lệnh, khuyên, hướng dẫn, mời mọc."],
f:["Ba ngôi tu, nous, vous, không có chủ ngữ: Parle ! Parlons ! Parlez !","Động từ -er bỏ -s ở ngôi tu: Mange ! (trừ trước en, y: Manges-en, Vas-y).","Bất quy tắc: être → sois, soyons, soyez; avoir → aie, ayons, ayez; savoir → sache; vouloir → veuillez.","Khẳng định: đại từ đứng sau, nối bằng gạch: Regarde-le ! Donne-moi ça ! Phủ định: đứng trước: Ne le regarde pas !"],
x:[["Ferme la fenêtre, s'il te plaît.","Đóng cửa sổ giúp mình."],["Allons au parc !","Chúng ta đi công viên đi!"],["Ne soyez pas en retard.","Đừng đến muộn nhé."],["Dis-moi la vérité.","Nói thật với tôi đi."]],
e:["Manges ! → Mange !","Donne-me → Donne-moi."],
en:"Let's go → Allons-y: dùng ngôi nous, không có từ tương đương let.",
q:[["(tu, écouter) ___ !","Écoute"],["(vous, avoir) ___ patience.","Ayez"],["(tu, le prendre) ___ !","Prends-le"]]};
LESSONS.I31={u:["Lịch sự: Je voudrais…, Pourriez-vous… ?","Khuyên: Tu devrais…","Mong muốn: J'aimerais…"],
f:["Gốc futur + đuôi imparfait: -ais, -ais, -ait, -ions, -iez, -aient.","Hay gặp: je voudrais, je pourrais, je devrais, j'aimerais, ce serait, il faudrait."],
x:[["Je voudrais un café, s'il vous plaît.","Cho tôi một ly cà phê."],["Pourriez-vous m'aider ?","Anh có thể giúp tôi không?"],["Tu devrais te reposer.","Bạn nên nghỉ ngơi."],["J'aimerais visiter Paris.","Tôi muốn đi thăm Paris."]],
e:["Je veux un café (hơi cộc ở cửa hàng) → Je voudrais un café.","je pourais → je pourrais (hai chữ r)."],
en:"would like → voudrais; could you → pourriez-vous; should → devrais.",
q:[["Vous ___ (pouvoir) répéter ?","pourriez"],["Tu ___ (devoir) dormir plus.","devrais"],["Nous ___ (aimer) partir tôt.","aimerions"]]};
LESSONS.I32={u:["Nối hai câu, thay cho danh từ đứng trước (tiền ngữ)."],
t:[["Đại từ","Chức năng","Ví dụ"],["qui","chủ ngữ","l'homme qui parle"],["que","tân ngữ trực tiếp","le film que je vois"],["où","nơi chốn, thời gian","la ville où j'habite"],["dont","thay de + danh từ","le livre dont je parle"]],
f:["Sau giới từ: lequel, laquelle, lesquels, lesquelles; à + lequel = auquel; de + lequel = duquel.","Với người sau giới từ thường dùng qui: la personne avec qui je travaille.","Nhấn mạnh: C'est… qui / C'est… que: C'est Lan qui a gagné."],
x:[["J'ai une amie qui parle japonais.","Tôi có một người bạn nói tiếng Nhật."],["Voici la maison que j'ai achetée.","Đây là ngôi nhà tôi đã mua."],["C'est le jour où je suis né.","Đó là ngày tôi sinh ra."],["Le projet dont tu parles est intéressant.","Dự án bạn nói tới rất thú vị."]],
e:["Le livre que je parle → le livre dont je parle.","la ville que j'habite → la ville où j'habite."],
en:"who / which / that tách thành qui / que theo chức năng; tiếng Pháp không lược bỏ được như the film I saw → le film que j'ai vu.",
q:[["La femme ___ chante est ma tante.","qui"],["Le restaurant ___ nous dînons est cher.","où"],["C'est un sujet ___ on parle beaucoup.","dont"]]};
LESSONS.I33={u:["Câu hỏi với từ để hỏi, với quel, và câu cảm thán."],
f:["Từ để hỏi: où, quand, comment, combien, pourquoi; qui (người); que / qu'est-ce que (vật); quoi (sau giới từ hoặc cuối câu).","Ba cách: Où tu vas ? / Où est-ce que tu vas ? / Où vas-tu ?","quel, quelle, quels, quelles + danh từ (hợp giống số): Quelle heure est-il ?","Cảm thán: Quel beau temps ! Comme c'est beau !"],
x:[["Pourquoi est-ce que tu apprends le français ?","Tại sao bạn học tiếng Pháp?"],["Qu'est-ce que vous faites ce week-end ?","Cuối tuần này anh chị làm gì?"],["Avec qui sors-tu ?","Bạn đi chơi với ai?"],["Quels films aimes-tu ?","Bạn thích những phim nào?"]],
e:["Qu'est-ce que tu habites ? → Où est-ce que tu habites ?","Quel est ta adresse ? → Quelle est ton adresse ?"],
en:"Giới từ đứng đầu câu: Who are you going with? → Avec qui vas-tu ?",
q:[["___ est-ce que tu pars ? – Demain.","Quand"],["___ âge as-tu ?","Quel"],["Tu penses à ___ ? (vật)","quoi"]]};
LESSONS.I34={u:["Các kiểu phủ định khác ngoài ne… pas."],
f:["ne… jamais (không bao giờ), ne… plus (không còn), ne… rien (không gì), ne… personne (không ai), ne… aucun(e) (không một), ne… ni… ni (không… cũng không), ne… que (chỉ: hạn chế, không phải phủ định).","Ở passé composé: rien, jamais, plus đứng trước phân từ (je n'ai rien vu); personne đứng sau (je n'ai vu personne).","sans + nguyên mẫu hoặc danh từ: sans parler, sans sucre."],
x:[["Il ne fume plus.","Anh ấy không hút thuốc nữa."],["Je n'ai jamais vu la mer.","Tôi chưa bao giờ thấy biển."],["Elle ne mange ni viande ni poisson.","Cô ấy không ăn thịt cũng không ăn cá."],["Je n'ai que dix euros.","Tôi chỉ có 10 euro."]],
e:["Je n'ai vu rien → Je n'ai rien vu.","Thêm pas thừa: Je ne vois pas personne → Je ne vois personne."],
en:"never, nothing, nobody đi với ne nhưng không có pas; only → ne… que.",
q:[["Mettez au négatif : Il a encore faim. (plus)","Il n'a plus faim."],["Je n'ai vu ___ dans la rue. (không ai)","personne"],["Il ___ boit ___ de l'eau. (chỉ)","ne / que"]]};
LESSONS.I35={u:["Thuật lại lời nói khi động từ dẫn ở hiện tại (il dit, elle demande)."],
f:["Câu trần thuật: dire que: Il dit qu'il est fatigué.","Câu hỏi có/không: demander si: Elle demande si tu viens.","Câu hỏi có từ để hỏi: giữ từ để hỏi; qu'est-ce que → ce que; qu'est-ce qui → ce qui.","Mệnh lệnh: dire de + nguyên mẫu. Đổi đại từ và tính từ sở hữu cho hợp ngôi."],
x:[["Il dit : « J'ai faim. » → Il dit qu'il a faim.","Anh ấy nói là anh ấy đói."],["Elle demande : « Tu viens ? » → Elle demande si je viens.","Cô ấy hỏi tôi có đến không."],["Il demande ce que nous faisons.","Anh ấy hỏi chúng tôi đang làm gì."],["Le professeur nous dit de nous asseoir.","Thầy bảo chúng tôi ngồi xuống."]],
e:["Il demande qu'est-ce que je veux → Il demande ce que je veux.","Elle demande que tu viens → Elle demande si tu viens."],
en:"if / whether → si; câu hỏi gián tiếp không đảo ngữ.",
q:[["« Où habites-tu ? » → Il me demande ___ j'habite.","où"],["« Ferme la porte ! » → Elle me dit ___ fermer la porte.","de"],["« Qu'est-ce que tu lis ? » → Il demande ___ je lis.","ce que"]]};
LESSONS.I36={u:["Hai hành động diễn ra cùng lúc, cùng chủ ngữ.","Chỉ cách thức, phương tiện hoặc điều kiện."],
f:["en + phân từ hiện tại; phân từ hiện tại = gốc của nous ở présent bỏ -ons + -ant: nous parlons → en parlant.","Bất quy tắc: être → étant, avoir → ayant, savoir → sachant.","Phân từ hiện tại không có en chủ yếu dùng trong văn viết, thay cho mệnh đề qui hoặc chỉ nguyên nhân."],
x:[["Il chante en se douchant.","Anh ấy vừa tắm vừa hát."],["C'est en pratiquant qu'on progresse.","Luyện tập thì mới tiến bộ."],["En prenant le métro, tu arriveras plus vite.","Đi tàu điện ngầm thì bạn sẽ đến nhanh hơn."],["Les étudiants ayant un visa peuvent travailler.","Sinh viên có visa có thể đi làm."]],
e:["Khác chủ ngữ: En arrivant, le téléphone a sonné → Quand je suis arrivé, le téléphone a sonné.","Sai gốc: en faiant → en faisant."],
en:"Giống -ing chỉ cách thức (by doing, while doing) nhưng phải có en.",
q:[["(lire) Je me détends en ___.","lisant"],["(être) ___ malade, il est resté chez lui.","Étant"],["Elle a appris l'anglais ___ regardant des films.","en"]]};
LESSONS.I37={u:["Nhiều động từ đi kèm một giới từ cố định, à hoặc de."],
f:["à + người: parler à, téléphoner à, répondre à, demander à, donner à.","de: parler de, avoir besoin de, se souvenir de, s'occuper de, avoir envie de.","Trước nguyên mẫu: commencer à, apprendre à, réussir à / arrêter de, essayer de, oublier de, décider de, finir de."],
x:[["J'ai téléphoné à ma mère.","Tôi đã gọi cho mẹ."],["Il a besoin d'aide.","Anh ấy cần giúp đỡ."],["J'apprends à nager.","Tôi đang học bơi."],["N'oublie pas de fermer la porte.","Đừng quên đóng cửa."]],
e:["téléphoner ma mère → téléphoner à ma mère.","essayer à faire → essayer de faire."],
en:"Nhiều động từ khác tiếng Anh: phone someone → téléphoner à quelqu'un; ask someone → demander à quelqu'un.",
q:[["Elle a décidé ___ partir.","de"],["Il commence ___ pleuvoir.","à"],["Je m'occupe ___ mon frère.","de"]]};
LESSONS.I38={u:["Diễn đạt việc đi, đến, về, quay lại."],
f:["aller (đi), venir (đến chỗ người nói), revenir (quay lại), rentrer (về nhà), retourner (quay về nơi cũ), partir (rời đi), arriver (đến nơi).","Các động từ này dùng être ở passé composé.","visiter + nơi chốn; aller voir / rendre visite à + người."],
x:[["Je viens du Việt Nam.","Tôi đến từ Việt Nam."],["Elle rentre chez elle à 19 h.","Cô ấy về nhà lúc 7 giờ tối."],["Nous avons visité le Louvre.","Chúng tôi đã tham quan bảo tàng Louvre."],["Je vais voir ma grand-mère.","Tôi đi thăm bà."]],
e:["visiter ma grand-mère → rendre visite à ma grand-mère / aller voir ma grand-mère.","Il a parti → Il est parti."],
en:"visit dùng được cho cả người lẫn nơi; visiter chỉ dùng cho nơi chốn.",
q:[["Ce week-end, je ___ mon oncle. (đi thăm)","vais voir"],["Ils sont ___ (partir) hier.","partis"],["Nous ___ (visiter) la cathédrale.","visitons"]]};
LESSONS.I39={u:["Việc sắp xảy ra hoặc dự định chắc chắn."],
f:["aller (présent) + nguyên mẫu: Je vais partir.","Phủ định bao quanh aller: Je ne vais pas partir.","Đại từ đứng trước nguyên mẫu: Je vais le voir. Câu hỏi: Tu vas venir ? / Vas-tu venir ?"],
x:[["Il va pleuvoir.","Trời sắp mưa."],["Nous allons déménager en mars.","Chúng tôi sẽ chuyển nhà vào tháng Ba."],["Je ne vais pas sortir ce soir.","Tối nay tôi sẽ không ra ngoài."],["Tu vas lui téléphoner ?","Bạn sẽ gọi cho anh ấy chứ?"]],
e:["Je vais ne pas sortir → Je ne vais pas sortir.","Je le vais voir → Je vais le voir."],
en:"be going to → aller + nguyên mẫu, cấu trúc gần như giống hệt.",
q:[["(nous, manger) ___ au restaurant.","Nous allons manger"],["Mettez au négatif : Elle va venir.","Elle ne va pas venir."],["Tu vas acheter ce livre ? – Oui, je vais ___ acheter.","l'"]]};
LESSONS.I40={u:["Hành động đã hoàn tất trong quá khứ."],
f:["avoir / être (présent) + phân từ quá khứ.","Phân từ: -er → -é; -ir → -i; nhiều dạng bất quy tắc: fait, pris, mis, dit, écrit, vu, lu, bu, eu, été, pu, voulu, su, venu, ouvert.","Dùng être với các động từ chỉ chuyển động hay thay đổi trạng thái (aller, venir, partir, arriver, entrer, sortir, monter, descendre, naître, mourir, rester, tomber, retourner) và mọi động từ phản thân; khi đó phân từ hợp với chủ ngữ.","Với avoir: phân từ hợp với COD đứng trước: la lettre que j'ai écrite."],
x:[["J'ai fini mes devoirs.","Tôi đã làm xong bài tập."],["Elle est partie hier.","Cô ấy đã đi hôm qua."],["Nous nous sommes rencontrés à Paris.","Chúng tôi đã gặp nhau ở Paris."],["Je n'ai pas compris.","Tôi không hiểu."]],
e:["Elle a allé → Elle est allée.","J'ai prendu → J'ai pris."],
en:"Dùng được với mốc thời gian quá khứ (hier, en 2020), khác present perfect; thường tương ứng với past simple.",
q:[["Ils ___ (venir) à la fête.","sont venus"],["Elle ___ (voir) un film.","a vu"],["Nous ___ (se lever) tôt.","nous sommes levés"]]};
LESSONS.I41={u:["Mốc thời gian, khoảng thời gian và trình tự sự việc."],
f:["il y a + khoảng thời gian = cách đây: Je suis arrivé il y a deux ans.","Ça fait / Il y a … que + hiện tại = đã được bao lâu: Ça fait un an que j'habite ici.","Trình tự: d'abord, ensuite, puis, enfin; avant de + nguyên mẫu; après + nguyên mẫu quá khứ.","Mốc tương đối khi kể chuyện: la veille (hôm trước), le lendemain (hôm sau), ce jour-là."],
x:[["Il est parti il y a dix minutes.","Anh ấy đi cách đây 10 phút."],["Ça fait trois mois que j'apprends le piano.","Tôi học piano được ba tháng rồi."],["D'abord, il a dîné, puis il est sorti.","Đầu tiên anh ấy ăn tối, sau đó ra ngoài."],["Le lendemain, il pleuvait.","Hôm sau trời mưa."]],
e:["Nhầm il y a (cách đây) với depuis (từ khi, vẫn tiếp diễn).","Khi kể chuyện quá khứ, dùng la veille / le lendemain thay cho hier / demain."],
en:"ago → il y a, nhưng đứng trước khoảng thời gian: two years ago → il y a deux ans.",
q:[["J'ai commencé ce travail ___ un mois.","il y a"],["___ fait deux heures que j'attends.","Ça"],["Après ___ mangé, il a fait la sieste.","avoir"]]};
LESSONS.I42={u:["Nhấn mạnh người hoặc vật chịu tác động của hành động."],
f:["être (đúng thì) + phân từ quá khứ (hợp với chủ ngữ) + par + tác nhân.","Présent: est construit; passé composé: a été construit; futur: sera construit.","Câu có chủ ngữ on thường bỏ tác nhân: On a volé ma voiture → Ma voiture a été volée.","Động từ chỉ cảm xúc, trạng thái hay dùng de: Il est aimé de tous."],
x:[["Ce livre est lu par des millions de lecteurs.","Cuốn sách này được hàng triệu người đọc."],["La maison a été vendue.","Ngôi nhà đã được bán."],["Le pont sera fini en 2027.","Cây cầu sẽ được hoàn thành năm 2027."],["Elle est respectée de ses collègues.","Cô ấy được đồng nghiệp kính trọng."]],
e:["Quên hợp giống số: Les lettres ont été envoyé → envoyées.","Sai thì của être: La tour a construite → La tour a été construite."],
en:"Giống câu bị động tiếng Anh, nhưng tiếng Pháp hay dùng on hơn: French is spoken here → On parle français ici.",
q:[["Mettez au passif : Le chat mange la souris.","La souris est mangée par le chat."],["Mettez au passif : On a annulé le concert.","Le concert a été annulé."],["Les résultats ___ (publier, futur passif) demain.","seront publiés"]]};
LESSONS.I43={u:["Mô tả bối cảnh, trạng thái trong quá khứ.","Thói quen trong quá khứ.","Hành động đang diễn ra thì bị một hành động khác (passé composé) cắt ngang."],
f:["Gốc = nous ở présent bỏ -ons, thêm -ais, -ais, -ait, -ions, -iez, -aient. Ngoại lệ: être → j'étais.","Passé composé: hành động chính, đã xong, có mốc rõ. Imparfait: nền, mô tả, lặp lại."],
x:[["Quand j'étais petit, j'habitais à Huế.","Hồi nhỏ tôi sống ở Huế."],["Il faisait beau et les enfants jouaient.","Trời đẹp và bọn trẻ đang chơi."],["Je dormais quand tu as appelé.","Tôi đang ngủ thì bạn gọi."],["Le dimanche, nous allions chez mes grands-parents.","Chủ nhật nào chúng tôi cũng sang nhà ông bà."]],
e:["Hành động cụ thể, đã xong mà dùng imparfait: Hier, je regardais un film et je me couchais → j'ai regardé… je me suis couché.","nous mangeions → nous mangions."],
en:"used to / was doing → imparfait; I did → passé composé.",
q:[["Avant, il ___ (fumer) beaucoup.","fumait"],["Nous ___ (être) fatigués.","étions"],["Je lisais quand il ___ (arriver).","est arrivé"]]};
LESSONS.I44={u:["Hành động xảy ra trước một hành động quá khứ khác."],
f:["avoir / être (imparfait) + phân từ quá khứ: j'avais fini, elle était partie.","Cách chọn avoir / être và hợp giống số giống passé composé.","Hay gặp trong câu gián tiếp quá khứ và câu giả định trái quá khứ (si + plus-que-parfait)."],
x:[["Quand je suis arrivé, le film avait commencé.","Khi tôi đến, phim đã bắt đầu rồi."],["Elle m'a dit qu'elle avait perdu son sac.","Cô ấy bảo tôi là cô ấy đã mất túi."],["Ils étaient déjà partis.","Họ đã đi rồi."],["Si j'avais su, je serais venu.","Nếu biết thì tôi đã đến."]],
e:["Dùng passé composé khi cần thể hiện việc xảy ra trước: Le train est parti quand je suis arrivé → Le train était parti…","Elle avait parti → Elle était partie."],
en:"Tương đương past perfect (had done).",
q:[["Il ___ (oublier) ses clés, alors il ne pouvait pas entrer.","avait oublié"],["Nous ___ (partir) avant la pluie.","étions partis"],["Elle a dit qu'elle ___ (finir).","avait fini"]]};
LESSONS.I45={u:["Thuật lại lời nói khi động từ dẫn ở quá khứ: phải lùi thì."],
t:[["Lời trực tiếp","Lời gián tiếp"],["présent","imparfait"],["passé composé","plus-que-parfait"],["futur simple","conditionnel présent"],["futur proche (va faire)","allait faire"]],
f:["Đổi mốc thời gian: aujourd'hui → ce jour-là; demain → le lendemain; hier → la veille; ici → là.","Imparfait, plus-que-parfait và conditionnel giữ nguyên."],
x:[["Il a dit : « Je suis malade. » → Il a dit qu'il était malade.","Anh ấy nói là anh ấy bị ốm."],["Elle a dit qu'elle viendrait le lendemain.","Cô ấy nói hôm sau cô ấy sẽ đến."],["Il m'a demandé si j'avais fini.","Anh ấy hỏi tôi đã xong chưa."],["Ils ont expliqué qu'ils allaient déménager.","Họ giải thích là họ sắp chuyển nhà."]],
e:["Không lùi thì: Il a dit qu'il est malade (chỉ chấp nhận khi điều đó vẫn đúng lúc nói).","Elle a dit qu'elle viendra demain → … qu'elle viendrait le lendemain."],
en:"Lùi thì giống tiếng Anh: will → would tương ứng futur → conditionnel.",
q:[["« J'aime ce film. » → Elle a dit qu'elle ___ ce film.","aimait"],["« Je partirai demain. » → Il a dit qu'il ___ le lendemain.","partirait"],["« J'ai perdu mon portable. » → Il a dit qu'il ___ son portable.","avait perdu"]]};
LESSONS.I46={u:["Diễn đạt các giai đoạn của một hành động: vừa xong, đang, sắp."],
f:["venir de + nguyên mẫu: vừa mới. Ở quá khứ: venait de.","être en train de + nguyên mẫu: đang (nhấn mạnh tiến trình).","être sur le point de + nguyên mẫu: sắp sửa (ngay lập tức).","aller + nguyên mẫu: sẽ (tương lai gần)."],
x:[["Je viens de rentrer.","Tôi vừa về."],["Elle est en train de cuisiner.","Cô ấy đang nấu ăn."],["Le train est sur le point de partir.","Tàu sắp chạy."],["Il venait de sortir quand tu as appelé.","Anh ấy vừa ra ngoài thì bạn gọi."]],
e:["Je viens de rentré → Je viens de rentrer (phải là nguyên mẫu).","Je suis en train de travaille → … de travailler."],
en:"have just done → venir de faire; be doing → être en train de faire.",
q:[["Ils ___ arriver. (vừa mới)","viennent d'"],["Ne parle pas, je suis ___ de réfléchir.","en train"],["Attention, le verre est ___ de tomber ! (sắp)","sur le point"]]};
LESSONS.I47={u:["Dự định, dự đoán, lời hứa trong tương lai; dùng sau quand khi nói về tương lai."],
f:["Nguyên mẫu (bỏ -e của động từ -re) + -ai, -as, -a, -ons, -ez, -ont: parlerai, finirai, prendrai.","Gốc bất quy tắc: être → ser-, avoir → aur-, aller → ir-, faire → fer-, venir → viendr-, voir → verr-, pouvoir → pourr-, vouloir → voudr-, devoir → devr-, savoir → saur-, falloir → il faudra.","si + présent → futur: S'il fait beau, nous sortirons."],
x:[["Demain, il fera beau.","Ngày mai trời sẽ đẹp."],["Je t'appellerai quand j'arriverai.","Tôi sẽ gọi bạn khi tôi đến."],["Nous verrons.","Để xem đã."],["Tu pourras venir ?","Bạn có thể đến không?"]],
e:["Quand j'arrive, je t'appellerai → Quand j'arriverai, je t'appellerai.","je pourai → je pourrai."],
en:"will + động từ; riêng sau when tiếng Anh dùng hiện tại, tiếng Pháp dùng futur (when I arrive → quand j'arriverai).",
q:[["Ils ___ (être) en vacances.","seront"],["Je ___ (faire) les courses demain.","ferai"],["Quand tu ___ (avoir) le temps, appelle-moi.","auras"]]};
LESSONS.I48={u:["Hành động hoàn tất trước một mốc hoặc một hành động khác trong tương lai.","Phỏng đoán về một việc đã xảy ra: Il aura oublié."],
f:["avoir / être (futur simple) + phân từ quá khứ: j'aurai fini, elle sera partie.","Hay đi sau quand, dès que, lorsque, après que."],
x:[["Quand tu arriveras, j'aurai fini.","Khi bạn đến, tôi đã xong rồi."],["Dès qu'il sera rentré, nous dînerons.","Ngay khi anh ấy về, chúng ta sẽ ăn tối."],["Elle n'est pas là ? Elle aura raté le bus.","Cô ấy chưa đến à? Chắc là lỡ xe buýt rồi."],["D'ici juin, nous aurons déménagé.","Đến tháng Sáu, chúng tôi đã chuyển nhà xong."]],
e:["Quand j'ai fini, je sortirai → Quand j'aurai fini, je sortirai.","Quên hợp giống với être: Elle sera partie."],
en:"Tương đương future perfect (will have done).",
q:[["Quand vous ___ (lire) ce livre, prêtez-le-moi.","aurez lu"],["Dès qu'elle ___ (arriver), on partira.","sera arrivée"],["Il est en retard ; il ___ (oublier) l'heure.","aura oublié"]]};
LESSONS.I49={u:["Điều tưởng tượng, không có thật ở hiện tại.","Thông tin chưa được xác nhận (văn báo chí)."],
f:["Gốc futur + -ais, -ais, -ait, -ions, -iez, -aient.","Đi với si + imparfait: Si j'étais riche, je voyagerais.","Conditionnel passé: aurais / serais + phân từ: điều tiếc nuối, không xảy ra."],
x:[["À ta place, je n'accepterais pas.","Ở vị trí của bạn, tôi sẽ không nhận."],["Dans un monde idéal, tout le monde aurait un travail.","Trong một thế giới lý tưởng, ai cũng có việc làm."],["Le ministre serait malade.","Nghe nói bộ trưởng bị ốm."],["J'aurais aimé venir.","Lẽ ra tôi rất muốn đến."]],
e:["Nhầm futur và conditionnel: je serai (sẽ) ≠ je serais (sẽ… nếu).","Si j'aurais → Si j'avais."],
en:"would + động từ → conditionnel; would have done → conditionnel passé.",
q:[["Si j'avais le temps, je ___ (lire) plus.","lirais"],["Nous ___ (vouloir) une chambre double.","voudrions"],["Il ___ (aimer, passé) partir, mais il ne pouvait pas.","aurait aimé"]]};
LESSONS.I50={u:["Ba loại câu điều kiện với si."],
t:[["Loại","Mệnh đề si","Mệnh đề chính"],["có thể xảy ra","si + présent","futur / présent / impératif"],["trái với hiện tại","si + imparfait","conditionnel présent"],["trái với quá khứ","si + plus-que-parfait","conditionnel passé"]],
f:["Không dùng futur hay conditionnel ngay sau si (si mang nghĩa nếu).","Có thể kết hợp: si + plus-que-parfait → conditionnel présent khi kết quả ở hiện tại: Si j'avais étudié, je serais médecin aujourd'hui."],
x:[["S'il pleut, je resterai à la maison.","Nếu trời mưa, tôi sẽ ở nhà."],["Si j'avais une voiture, je t'emmènerais.","Nếu có xe, tôi sẽ chở bạn."],["Si tu m'avais prévenu, je serais venu.","Nếu bạn báo trước, tôi đã đến."],["Si tu as faim, mange !","Nếu đói thì ăn đi!"]],
e:["Si j'aurais su → Si j'avais su.","Si tu viendras → Si tu viens."],
en:"Tương ứng conditional loại 1, 2, 3 trong tiếng Anh.",
q:[["Si je ___ (gagner) au loto, j'achèterais une maison.","gagnais"],["Si tu travailles, tu ___ (réussir).","réussiras"],["S'il avait couru, il ___ (attraper) le bus.","aurait attrapé"]]};
LESSONS.I51={u:["Sau il faut que, vouloir que, các cảm xúc + que (content que, avoir peur que), sự nghi ngờ (douter que) và một số liên từ (pour que, bien que, avant que, à condition que)."],
f:["Gốc = ils ở présent bỏ -ent, thêm -e, -es, -e, -ions, -iez, -ent: qu'il finisse, que je parte.","Bất quy tắc: être (que je sois), avoir (que j'aie), aller (que j'aille), faire (que je fasse), pouvoir (que je puisse), savoir (que je sache), vouloir (que je veuille).","Cùng chủ ngữ thì dùng nguyên mẫu: Je veux partir (không nói je veux que je parte).","Subjonctif passé: aie / sois + phân từ: Je suis content que tu sois venu."],
x:[["Il faut que tu dormes.","Bạn cần phải ngủ."],["Je veux que vous soyez heureux.","Tôi muốn các bạn hạnh phúc."],["Bien qu'il pleuve, nous sortons.","Dù trời mưa, chúng tôi vẫn ra ngoài."],["Je pense qu'il viendra. / Je ne pense pas qu'il vienne.","Tôi nghĩ anh ấy sẽ đến. / Tôi không nghĩ anh ấy sẽ đến."]],
e:["Il faut que tu viens → Il faut que tu viennes.","Je pense qu'il soit là → Je pense qu'il est là (penser khẳng định đi với indicatif)."],
en:"Tiếng Anh gần như không còn thức này: I want you to come → Je veux que tu viennes.",
q:[["Il faut que nous ___ (partir).","partions"],["Je suis content que tu ___ (être) là.","sois"],["Avant qu'il ___ (faire) nuit, rentrons.","fasse"]]};
LESSONS.I52={u:["Nối các ý: nguyên nhân, kết quả, mục đích, đối lập."],
t:[["Quan hệ","+ mệnh đề","+ danh từ / nguyên mẫu"],["nguyên nhân","parce que, puisque, comme","à cause de, grâce à"],["kết quả","donc, alors, c'est pourquoi, si bien que","—"],["mục đích","pour que, afin que (+ subjonctif)","pour, afin de"],["đối lập","mais, pourtant, alors que, bien que (+ subjonctif)","malgré"]],
f:["comme đứng đầu câu: Comme il pleut, je reste.","puisque nêu lý do người nghe đã biết."],
x:[["Je suis resté chez moi parce que j'étais malade.","Tôi ở nhà vì bị ốm."],["Grâce à toi, j'ai réussi.","Nhờ bạn mà tôi thành công."],["Je parle lentement pour que tu comprennes.","Tôi nói chậm để bạn hiểu."],["Malgré la fatigue, il continue.","Dù mệt, anh ấy vẫn tiếp tục."]],
e:["malgré qu'il soit → bien qu'il soit.","Dùng à cause de cho kết quả tốt: À cause de lui, j'ai réussi → Grâce à lui, j'ai réussi."],
en:"because of → à cause de hoặc grâce à tùy kết quả xấu hay tốt; so that → pour que + subjonctif.",
q:[["___ la neige, le vol est annulé.","À cause de"],["Il étudie ___ réussir l'examen.","pour"],["Elle est fatiguée ; ___, elle va au travail. (đối lập)","pourtant"]]};
